Here is the commit message:
gpio: pci-idio-16: Fix port memory offset for get_multiple
 callback

The ioread8 function expects a memory offset argument. This patch fixes
the ports array to provide the memory addresses of the respective device
I/O registers.

Fixes: 810ebfc5efca ("gpio: pci-idio-16: Implement get_multiple callback")
Signed-off-by: William Breathitt Gray <vilhelm.gray@gmail.com>
Signed-off-by: Linus Walleij <linus.walleij@linaro.org>

Here is the root cause:
The bug was caused by the incorrect initialization of the `ports` array, which was defined as `u8 __iomem` instead of `void __iomem *`. This led to passing incorrect memory offsets to the `ioread8` function, resulting in improper access to the device I/O registers during the `get_multiple` callback.

Here is the patch:

 static int idio_16_gpio_get_multiple(struct gpio_chip *chip,
 	unsigned long *mask, unsigned long *bits)
 {
 	struct idio_16_gpio *const idio16gpio = gpiochip_get_data(chip);
 	size_t i;
 	const unsigned int gpio_reg_size = 8;
 	unsigned int bits_offset;
 	size_t word_index;
 	unsigned int word_offset;
 	unsigned long word_mask;
 	const unsigned long port_mask = GENMASK(gpio_reg_size - 1, 0);
 	unsigned long port_state;
-	u8 __iomem ports[] = {
-		idio16gpio->reg->out0_7, idio16gpio->reg->out8_15,
-		idio16gpio->reg->in0_7, idio16gpio->reg->in8_15,
+	void __iomem *ports[] = {
+		&idio16gpio->reg->out0_7, &idio16gpio->reg->out8_15,
+		&idio16gpio->reg->in0_7, &idio16gpio->reg->in8_15,
 	};

 	/* clear bits array to a clean slate */
 	bitmap_zero(bits, chip->ngpio);

 	/* get bits are evaluated a gpio port register at a time */
 	for (i = 0; i < ARRAY_SIZE(ports); i++) {
 		/* gpio offset in bits array */
 		bits_offset = i * gpio_reg_size;

 		/* word index for bits array */
 		word_index = BIT_WORD(bits_offset);

 		/* gpio offset within current word of bits array */
 		word_offset = bits_offset % BITS_PER_LONG;

 		/* mask of get bits for current gpio within current word */
 		word_mask = mask[word_index] & (port_mask << word_offset);
 		if (!word_mask) {
 			/* no get bits in this port so skip to next one */
 			continue;
 		}

 		/* read bits from current gpio port */
-		port_state = ioread8(ports + i);
+		port_state = ioread8(ports[i]);

 		/* store acquired bits at respective bits array offset */
 		bits[word_index] |= port_state << word_offset;
 	}

 	return 0;
 }



